{"fw_ld6_shelter_civ_1_0001","shelter",3,"reg=civilian,worker|mood=funny",{1,"Pass the Spam",2,"We got Spam?",1,"We HAD Spam, I watched you stuff it in your goddamn bag",2,"That's my Spam",3,"It's a can of pig parts, nobody owns it",2,"I own it, I carried that goddamn can four miles"}},
{"fw_ld6_shelter_civ_1_0002","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"This one says 1989",2,"So?",1,"So it's been sitting in somebody's cabinet since before you could drive",2,"Smell it",1,"Why the hell would I smell it, you smell it",3,"If it smells like feet we're not eating it"}},
{"fw_ld6_shelter_civ_1_0003","shelter",3,"reg=civilian,worker|mood=grim",{1,"Half a can each",2,"That's it?",1,"I counted twice, that's it",2,"You counted cans, you didn't count how fucking hungry I am",3,"Nobody's counting that..."}},
{"fw_ld6_shelter_civ_1_0004","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Had a dream about a Hardee's biscuit last night",2,"Yeah?",1,"Woke up chewing my sleeve",3,"Explains the drool"}},
{"fw_ld6_shelter_civ_1_0005","shelter",3,"reg=civilian,family,worker,rescue",{1,"Is this one bulging?",2,"Where",1,"The top, see, it's puffed up",2,"Put it down",1,"Put it down and then what",3,"Throw it far as you can and don't shake it, for God's sake"}},
{"fw_ld6_shelter_civ_1_0006","shelter",4,"reg=civilian,family,worker,rescue",{1,"Where's the can opener",2,"In the bag",1,"I looked in the bag",2,"Look again",1,"...it was under the bag",3,"It's always under the bag"}},
{"fw_ld6_shelter_civ_1_0007","shelter",3,"reg=civilian,worker",{1,"Cold ravioli straight out of the can, I'm eating like a goddamn raccoon",2,"Better than the beans",3,"Beans are all we got, so eat the beans",1,"Don't say beans, I just ate"}},
{"fw_ld6_shelter_civ_1_0008","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"My mama's cornbread, the edges all crispy",2,"Cast iron",1,"Cast iron and bacon grease, none of that shortening garbage",2,"Stop, I can smell it",1,"Sorry",3,"No, keep going, I like it"}},
{"fw_ld6_shelter_civ_1_0009","shelter",3,"reg=civilian,family,worker,rescue",{1,"Who's been in the peaches",2,"Not me",3,"Not me",1,"Then the can opened itself and the lid threw itself in the damn trash",2,"Okay, a little bit me"}},
{"fw_ld6_shelter_civ_1_0010","shelter",2,"reg=civilian,family,worker,rescue",{1,"Pop-Tart for a cigarette",2,"Frosted?",1,"Plain, it's what I got",2,"Plain's an insult, I'll do half a cigarette"}},
{"fw_ld6_shelter_civ_1_0011","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Vienna sausages, who drinks the juice",2,"Me",1,"That's disgusting",2,"That's salt, I'm replacing what I sweat out",3,"Let 'em, more for us"}},
{"fw_ld6_shelter_civ_1_0012","shelter",3,"reg=civilian,worker",{1,"I'm so hungry my stomach's eating itself",2,"That's just the beans talking",1,"No, listen, that's an actual growl",2,"...Jesus Christ, you sound like a dog in a ditch",3,"Somebody feed that thing"}},
{"fw_ld6_shelter_civ_1_0013","shelter",3,"reg=civilian,worker|mood=angry",{1,"Somebody took more than their half",2,"Don't look at ME!",1,"I'm looking at the fuckin' can, it was full, now it's not",2,"Maybe it leaked",3,"Cans don't leak into a goddamn spoon!"}},
{"fw_ld6_shelter_civ_1_0014","shelter",3,"reg=civilian,worker",{1,"I drank the pickle juice",2,"All of it?",1,"All of it, my body said do it",3,"Your body's an idiot"}},
{"fw_ld6_shelter_civ_1_0015","shelter",4,"reg=civilian,family,worker,rescue",{1,"Anybody got ketchup?",2,"We got packets",1,"From where?",2,"My glove box, McDonald's, I've been saving them since March",3,"Of course you have"}},
{"fw_ld6_shelter_civ_1_0016","shelter",2,"reg=civilian,family,worker,rescue",{1,"Saltines in my bedroll again",2,"Crumbs everywhere?",1,"I'm gonna wake up with a waffle pattern on my face"}},
{"fw_ld6_shelter_civ_1_0017","shelter",4,"reg=civilian,family,worker,rescue|mood=warm|world=building",{1,"It's Doyle's birthday",2,"Is it?",1,"Forty-one today, found a Little Debbie in the back of the pantry and stuck a match in it",2,"A match?",1,"A candle's too much to ask for",3,"Happy birthday, Doyle, you old bastard",4,"Don't blow it out, we need the match"}},
{"fw_ld6_shelter_civ_1_0018","shelter",3,"reg=civilian,worker",{1,"Bread's got a green corner",2,"Cut it off",1,"The whole slice has a green feeling",3,"It's penicillin, eat the damn thing"}},
{"fw_ld6_shelter_civ_1_0019","shelter",3,"reg=civilian,worker",{1,"This chili tastes like a foot",2,"Whose foot?",1,"Doesn't matter, I'm finishing it",3,"Respect"}},
{"fw_ld6_shelter_civ_1_0020","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Fourth of July we did hot dogs on the grill",2,"I know, I was there",1,"Wasn't it a good one?",2,"It was",1,"Yeah..."}},
{"fw_ld6_shelter_civ_1_0021","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Warm Mountain Dew is a crime",2,"It's a crime I used to commit daily",3,"I'd still ask you for a sip",2,"You'd have had to find your own crime"}},
{"fw_ld6_shelter_civ_1_0022","shelter",2,"reg=civilian,family,worker,rescue",{1,"I found hot sauce!",2,"Where",1,"Back of the cabinet, a Tabasco, a whole one",2,"Get it over here, I'll drink it"}},
{"fw_ld6_shelter_civ_1_0023","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Who put the jerky in my sock?",2,"That's where I hide it",1,"Why in a sock",2,"Nobody's gonna take a sock",3,"I would've, if I'd known"}},
{"fw_ld6_shelter_civ_1_0024","shelter",2,"reg=civilian,family,worker,rescue",{1,"Is Kool-Aid still safe if it's grape?",2,"Safe from what",1,"I dunno, it's purple, nothing in nature's that purple",2,"Drink it and see"}},
{"fw_ld6_shelter_civ_1_0025","shelter",4,"reg=civilian,family,worker,rescue",{1,"Eat something",2,"Not hungry",1,"You haven't eaten since yesterday",2,"I said I'm not hungry",3,"Just leave the can next to 'em",1,"Fine, it's right here"}},
{"fw_ld6_shelter_civ_1_0026","shelter",2,"reg=civilian,family,worker,rescue",{1,"Chew it slow, it lasts longer",2,"That's not how food works",1,"It's how my stomach works, it thinks it's getting more"}},
{"fw_ld6_shelter_civ_1_0027","shelter",3,"reg=civilian,worker",{1,"I'd eat a possum right now",2,"A raw possum",1,"With a little salt, yeah",3,"You ever seen a possum up close?"}},
{"fw_ld6_shelter_civ_1_0028","shelter",2,"reg=civilian,worker|mood=angry",{1,"You opened the last can of the good stuff without asking",2,"It was open already",1,"It was OPEN because you opened it!",2,"I'm NOT fighting about goddamn chili!"}},
{"fw_ld6_shelter_civ_1_0029","shelter",2,"reg=civilian,family,worker,rescue",{1,"I made a sandwich",2,"Out of what",1,"Bread and a feeling",2,"Give me half the feeling"}},
{"fw_ld6_shelter_civ_1_0030","shelter",3,"reg=civilian,worker|mood=funny|world=summer",{1,"Who the hell packs a can of cranberry sauce?",2,"It was Thanksgiving in my head",1,"It's summer",2,"My head's got its own calendar",3,"Open it, I'll eat anything"}},
{"fw_ld6_shelter_civ_1_0031","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Know what I remember about my brother?",2,"What?",1,"He'd split his sandwich without asking if I was hungry",2,"Even when he needed it?",1,"Especially then. That's what stays with me"}},
{"fw_ld6_shelter_civ_1_0032","shelter",3,"reg=civilian,family,worker,rescue|day=1,8",{1,"Anybody else's mouth taste like pennies",2,"Since Saturday",3,"I thought that was just me"}},
{"fw_ld6_shelter_civ_1_0033","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"We got any of that Kool-Aid powder left?",2,"The red",1,"Red's fine, I just wanna taste something",3,"Put it in the canteen, make it look like blood, scare the neighbors"}},
{"fw_ld6_shelter_civ_1_0034","shelter",2,"reg=civilian,family,worker,rescue|mood=sad|world=building",{1,"You ever just stand in front of an open fridge",2,"Every night",1,"Even though it's off, I stand there, I feel nothing",2,"Yeah, no cold, just the smell"}},
{"fw_ld6_shelter_civ_1_0035","shelter",2,"reg=civilian,worker",{1,"There's a jar of something in the cabinet",2,"What is it?",1,"I can't read the label, it's gone brown, it might be applesauce",2,"It might be anything",1,"It's got a lid, that counts for something"}},
{"fw_ld6_shelter_civ_1_0036","shelter",2,"reg=civilian,family,worker,rescue",{1,"Used to say, last cigarette",2,"Every day?",1,"Every day I found another excuse",2,"And somebody asking for a drag",1,"Fine, but I watched their lips like they were stealing my wallet"}},
{"fw_ld6_shelter_civ_1_0037","shelter",3,"reg=civilian,worker|mood=angry",{1,"Who's been in my cigarettes?",2,"Nobody",1,"There were nine",2,"Maybe you counted wrong",1,"I count everything, there were NINE!",3,"Check your pocket, hon"}},
{"fw_ld6_shelter_civ_1_0038","shelter",3,"reg=civilian,worker",{1,"Lighter's out of fluid",2,"Flick it harder",1,"It's fucking empty, harder doesn't fix empty!",2,"Matches?",3,"Four, and one's wet"}},
{"fw_ld6_shelter_civ_1_0039","shelter",3,"reg=civilian,worker",{1,"I quit in May",2,"And?",1,"And I'm bumming one off you right now",3,"Forty days, that's a record for you"}},
{"fw_ld6_shelter_civ_1_0040","shelter",2,"reg=civilian,worker",{1,"Don't blow it at me",2,"It's one cigarette",1,"I'm trying to quit, you prick, it's like waving a steak at a dog",2,"Then go sit over there"}},
{"fw_ld6_shelter_civ_1_0041","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Skoal's all I got left and I'm out of cups",2,"Use a can",1,"The can's got beans in it",3,"Then eat the beans"}},
{"fw_ld6_shelter_civ_1_0042","shelter",2,"reg=civilian,family,worker,rescue",{1,"Found a cigar in the drawer",2,"What kind?",1,"White Owl, probably older than you",2,"Light it, I wanna see your face"}},
{"fw_ld6_shelter_civ_1_0043","shelter",3,"reg=civilian,worker",{1,"Phone book pages make decent rolling paper",2,"You've done this?",1,"Once, eighth grade, threw up everywhere, never again",3,"Great, let's all do it"}},
{"fw_ld6_shelter_civ_1_0044","shelter",3,"reg=civilian,worker",{1,"I'm so wired for a smoke I'm gonna bite somebody",2,"Bite a boot",3,"Bite the can, it's closer",1,"Y'all are no help"}},
{"fw_ld6_shelter_civ_1_0045","shelter",2,"reg=civilian,family,worker,rescue",{1,"Four matches left",2,"And one lighter that works when it feels like it",1,"So nobody waste any"}},
{"fw_ld6_shelter_civ_1_0046","shelter",2,"reg=civilian,family,worker,rescue",{1,"That's pipe tobacco, smells just like my granddaddy",2,"You want it?",1,"Just let me smell it for a minute"}},
{"fw_ld6_shelter_civ_1_0047","shelter",4,"reg=civilian,family,worker,rescue|mood=sad",{1,"My dad smoked Winstons",2,"Mine did too",1,"Bought a pack at the gas station once just to smell it",2,"Did it work?",1,"It smelled like my dad",3,"Yeah, it would"}},
{"fw_ld6_shelter_civ_1_0048","shelter",3,"reg=civilian,family,worker,rescue|mood=angry|world=inside",{1,"You can't smoke in here",2,"We're in a house with no power",1,"It's a house with a baby",2,"Where's the baby",1,"...there's no baby, it's the principle"}},
{"fw_ld6_shelter_civ_1_0049","shelter",3,"reg=civilian,worker|mood=angry",{1,"It's so fucking hot my shirt's glued to the chair and the water's warm as spit, I can't even sit still",2,"Peel it off then",1,"I did, it made a noise",3,"We heard"}},
{"fw_ld6_shelter_civ_1_0050","shelter",2,"reg=civilian,worker|mood=angry",{1,"Canteen water's the temperature of spit and I'm drinking it anyway, what the fuck else am I gonna do",2,"Drink it!",1,"I am, it tastes like drinking myself"}},
{"fw_ld6_shelter_civ_1_0051","shelter",4,"reg=civilian,family,worker,rescue|mood=sad",{1,"I keep reaching for the fan switch",2,"There's no power",1,"I know there's no power, my hand doesn't know",2,"Mine either",3,"It's the little things that get you"}},
{"fw_ld6_shelter_civ_1_0052","shelter",2,"reg=civilian,family,worker,rescue",{1,"Would you pay a hundred bucks for a bag of ice",2,"From the Kwik-Mart?",1,"From anywhere",2,"Two hundred, and I'd let you keep the bag"}},
{"fw_ld6_shelter_civ_1_0053","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"There's one mosquito, ONE, and it's been in my left ear for an hour!",2,"Slap it",1,"I can't, it's a relationship now",3,"Slap yourself then, I'm trying to sleep"}},
{"fw_ld6_shelter_civ_1_0054","shelter",3,"reg=civilian,worker",{1,"I got chigger bites in places I'm not gonna name",2,"Then don't name them",1,"They itch like hell",2,"Stop SCRATCHING, you're making it worse!",3,"Nothing's stopping that, it'll go till Sunday"}},
{"fw_ld6_shelter_civ_1_0055","shelter",3,"reg=civilian,family,worker,rescue",{1,"Check my back, I felt something",2,"Hold still",1,"Is it a tick?",2,"It's a tick",1,"GET IT OFF!",2,"Stop wiggling or I'm taking skin with it"}},
{"fw_ld6_shelter_civ_1_0056","shelter",3,"reg=civilian,worker",{1,"Gnats in my eyes, gnats in my mouth, I'm eating fucking gnats",2,"Close your mouth",1,"I'd have to stop talking, and where's the fun in that",3,"There's the fun"}},
{"fw_ld6_shelter_civ_1_0057","shelter",3,"reg=civilian,worker|mood=funny|world=building",{1,"Roach on the wall the size of my thumb",2,"Kill the bastard",1,"I'm not touching it",2,"Then name the bastard, he lives here now",3,"Name him Walt"}},
{"fw_ld6_shelter_civ_1_0058","shelter",3,"reg=civilian,worker",{1,"Hornet's been in the room since lunch",2,"Leave it alone and it leaves you alone",1,"That's not what my cousin said, he got stung on the lip, swelled up like a goddamn tomato",3,"Then don't kiss it"}},
{"fw_ld6_shelter_civ_1_0059","shelter",3,"reg=civilian,worker|mood=funny",{1,"Who stinks",2,"Everybody stinks",1,"No, somebody stinks worse, I can pick it out, it's a goddamn skill",3,"It's your boots",1,"It's NOT my boots!"}},
{"fw_ld6_shelter_civ_1_0060","shelter",4,"reg=civilian,worker|world=door",{1,"It's your turn to empty the bucket",2,"I emptied it yesterday",1,"Yesterday was a whole day ago!",2,"Fine, hold the fucking door, don't let it slam",3,"Lord, the things we say now"}},
{"fw_ld6_shelter_civ_1_0061","shelter",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Smell that?",2,"Smell what",1,"Never mind, forget it, it's nothing",2,"No, say it",1,"Smoke, somewhere, somebody's burning something..."}},
{"fw_ld6_shelter_civ_1_0062","shelter",3,"reg=civilian,family,worker,rescue",{1,"Heat rash under my arms, between my toes, everywhere, I'm a map of misery",2,"Powder helps",1,"We got powder?",2,"We had powder",3,"Check the bag, there's a can of something"}},
{"fw_ld6_shelter_civ_1_0063","shelter",2,"reg=civilian,family,worker,rescue|mood=funny|world=building",{1,"Can you imagine a ceiling fan right now",2,"I'm imagining it",1,"A little chain, you pull it, click click click",2,"Stop, you're making it worse"}},
{"fw_ld6_shelter_civ_1_0064","shelter",3,"reg=civilian,family,worker,rescue",{1,"You ever been this sweaty?",2,"Once, church picnic, Mamaw's sun tea was in a jar on the counter and I drank the whole gallon",1,"What's that got to do with sweat",2,"Nothing, I just thought of the tea",3,"I'd marry that tea"}},
{"fw_ld6_shelter_civ_1_0065","shelter",2,"reg=civilian,worker|mood=angry",{1,"If I don't get out of this shirt I'm gonna die in it, it's growing on me",2,"Take the fucking shirt off, nobody cares",1,"Then I'm in a house with strangers, half dressed",2,"We've seen worse, believe me, we're all disgusting"}},
{"fw_ld6_shelter_civ_1_0066","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"You were snoring",2,"I don't snore",1,"It was like a chainsaw in a trash can",2,"That was the building",3,"That was NOT the building!"}},
{"fw_ld6_shelter_civ_1_0067","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"You talked in your sleep last night",2,"What'd I say",1,"You said 'don't tell Mom'",2,"...I don't remember",1,"Tell her what?",2,"I really don't remember"}},
{"fw_ld6_shelter_civ_1_0068","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"I keep waking up reaching for my keys",2,"What for",1,"I dunno, to leave, I think",2,"Where would you go",1,"That's the thing, nowhere, I just wake up reaching"}},
{"fw_ld6_shelter_civ_1_0069","shelter",3,"reg=civilian,worker",{1,"This floor is killing my back",2,"Put your jacket under it",1,"It's under it, my back's still on the floor",3,"That's the problem with floors"}},
{"fw_ld6_shelter_civ_1_0070","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"Is that tapping?",2,"Where",1,"Over there, hush, listen",2,"That's the pipes, they're cooling",1,"Pipes don't cool, the water's off",3,"Well then I don't know"}},
{"fw_ld6_shelter_civ_1_0071","shelter",2,"reg=civilian,family,worker,rescue|mood=sad|world=building",{1,"I miss the sound of the refrigerator",2,"The what",1,"The motor, you know, the hum, you never hear it till it's gone",2,"Yeah, the whole house is wrong without it",1,"It's like somebody died in the next room"}},
{"fw_ld6_shelter_civ_1_0072","shelter",4,"reg=civilian,family,worker,rescue",{1,"Who's humming?",2,"Not me",1,"It's the same three notes",3,"It's you, you hum when you're nervous",1,"...oh, sorry"}},
{"fw_ld6_shelter_civ_1_0073","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Poke me twice when it's my turn",2,"Twice?",1,"I'm a heavy sleeper, once won't do it",2,"Twice then, and a third time if you cuss at me"}},
{"fw_ld6_shelter_civ_1_0074","shelter",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"You gonna sleep in your boots again?",2,"What if we have to go",1,"We're not going anywhere tonight",2,"Then I'll take 'em off in the morning"}},
{"fw_ld6_shelter_civ_1_0075","shelter",3,"reg=civilian,family,worker,rescue",{1,"Can't sleep",2,"Count something",1,"I did, I counted the cans, we got eleven, I counted again and we got nine",3,"Don't count anymore"}},
{"fw_ld6_shelter_civ_1_0076","shelter",4,"reg=civilian,family,worker,rescue|mood=sad",{1,"If I had a pillow I'd marry it",2,"You can have my jacket",1,"Does it smell like you",2,"Yes",1,"Then forget it",3,"Take mine, it smells like dog"}},
{"fw_ld6_shelter_civ_1_0077","shelter",3,"reg=civilian,family,worker,rescue",{1,"You hear that clock?",2,"What clock",1,"There's a ticking, somewhere, a watch maybe",2,"It's mine, it's on my wrist",1,"It's LOUD!",3,"It's the only thing left that works properly, leave it alone"}},
{"fw_ld6_shelter_civ_1_0078","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"I had a dream we were all back at the house and the TV was on",2,"What was on",1,"Nothing, just the TV and somebody cooking, and I woke up crying",2,"I'm sorry",1,"Best dream I've had all week"}},
{"fw_ld6_shelter_civ_1_0079","shelter",3,"reg=civilian,worker|mood=angry",{1,"Everybody just shut the fuck UP for five minutes!",2,"Nobody's talking",1,"You're breathing, the WHOLE room's breathing!",3,"...somebody's tired"}},
{"fw_ld6_shelter_civ_1_0080","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Somebody's grinding their teeth",2,"It's you",1,"It's not me",2,"It's definitely you, it's like gravel in a blender",1,"Okay, maybe it's me"}},
{"fw_ld6_shelter_civ_1_0081","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Is that a king?",2,"It's a Dr Pepper cap with a Pepsi cap on top",1,"That's a mistake with a cap on it",3,"It's a king if you say so..."}},
{"fw_ld6_shelter_civ_1_0082","shelter",3,"reg=civilian,family,worker,rescue",{1,"Rook, you got any trump?",2,"I'm not telling you",1,"I'm your PARTNER!",2,"You'd know, you've been watching me play for an hour"}},
{"fw_ld6_shelter_civ_1_0083","shelter",4,"reg=civilian,worker|mood=angry",{1,"You reneged",2,"I did not",1,"You had a heart, you played a spade",2,"I mixed it up",1,"Mixed it up my ass!",3,"Watch your mouth, there's women present"}},
{"fw_ld6_shelter_civ_1_0084","shelter",3,"reg=civilian,family,worker,rescue",{1,"Gin!",2,"Gin?!",1,"Gin, read 'em and weep",2,"That's eleven cans you owe me",1,"I don't have eleven cans",3,"That's a lot of beans to owe"}},
{"fw_ld6_shelter_civ_1_0085","shelter",4,"reg=civilian,family,worker,rescue",{1,"Double six",2,"You can't, you played it",1,"I'm checking",3,"Y'all are loud",1,"It's a game, it's allowed to be loud"}},
{"fw_ld6_shelter_civ_1_0086","shelter",3,"reg=civilian,family,worker,rescue",{1,"You're cheating at solitaire",2,"Against who",1,"Against me, I'm sitting right here",3,"Against the cards, they started it"}},
{"fw_ld6_shelter_civ_1_0087","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Twenty questions, I'm thinking of something",2,"Animal, vegetable, or mineral",1,"Mineral",2,"Is it bigger than a breadbox",1,"What the hell is a breadbox",2,"I don't know, my mama said it"}},
{"fw_ld6_shelter_civ_1_0088","shelter",2,"reg=civilian,family,worker,rescue",{1,"Hangman, I'll go first",2,"E",1,"No E",2,"A",1,"No A",2,"What's the word",1,"Rhythm"}},
{"fw_ld6_shelter_civ_1_0089","shelter",2,"reg=civilian,family,worker,rescue|mood=funny|world=building",{1,"Somebody found a Monopoly box in the closet",2,"Is everything in it?",1,"No thimble, and half the money's gone",2,"So it's Monopoly without the good parts",1,"It's Kentucky Monopoly"}},
{"fw_ld6_shelter_civ_1_0090","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"There's fifty-one cards in the deck",2,"Which one's missing?",1,"The seven of clubs",2,"I always hated that card",1,"You've been playing with the missing card, that's why you keep winning"}},
{"fw_ld6_shelter_civ_1_0091","shelter",3,"reg=civilian,family,worker,rescue",{1,"You wanna see something?",2,"What",1,"Stick your knife in the floor between your fingers, fast as you can",2,"I'm not doing that",1,"Mumblety-peg, everybody did it when I was little",3,"Everybody lost a finger when you were little"}},
{"fw_ld6_shelter_civ_1_0092","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Would you rather eat a raw possum or drink a warm Budweiser?",2,"Warm Budweiser",1,"That's too easy, you've done it before",2,"I did it at a fish fry, I was fine",3,"Twice, I was there"}},
{"fw_ld6_shelter_civ_1_0093","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"County fair last August, I won a goldfish",2,"Did it live?",1,"Three whole days",2,"That's a good run for a fair goldfish",1,"His name was Bruce",3,"Rest in peace, Bruce..."}},
{"fw_ld6_shelter_civ_1_0094","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"You ever go to the drive-in out past Radcliff?",2,"Every Saturday in high school",1,"We never watched the movie",2,"Nobody watched the movie",3,"I watched the movie, I was the designated driver and I'm still mad about it"}},
{"fw_ld6_shelter_civ_1_0095","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"My granddaddy cut tobacco till he was seventy-nine, hands like a catcher's mitt",1,"He could pick up a hot coal and not say a word",2,"He'd have hated all this",1,"He'd have sat there and said it was God's business, and gone to sleep"}},
{"fw_ld6_shelter_civ_1_0096","shelter",4,"reg=civilian,family,worker,rescue|mood=sad",{1,"First car I had, you could watch the road go by through a hole in the floor",2,"What was it?",1,"'78 Nova, I carried a coffee can of water for the radiator",2,"And you loved it",1,"More than anything, I'd take it back right now with the hole",3,"I'd take it back without the hole"}},
{"fw_ld6_shelter_civ_1_0097","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Homecoming at church, all the tables out in the yard",2,"Forty kinds of dessert",1,"And Opal's banana pudding went first, always",2,"Nobody could touch Opal's banana pudding",3,"Nobody even tried"}},
{"fw_ld6_shelter_civ_1_0098","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Dad took me to Nolin Lake once, I lost his good lure on the first cast",2,"Did he yell?",1,"He said well, now it's a lake lure, and kept on fishing",2,"That's a good dad",1,"It was a good dad"}},
{"fw_ld6_shelter_civ_1_0099","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"First Saturday in May, my uncle Roy put on that hat",2,"The yellow one?",1,"With the feathers, he thought he looked like a mint julep",3,"He looked like a canary"}},
{"fw_ld6_shelter_civ_1_0100","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I used to spend whole Saturdays at the mall",2,"Doing what?",1,"Nothing, just walking around with a pretzel looking at stuff I couldn't afford",2,"God, that sounds good right now"}},
{"fw_ld6_shelter_civ_1_0101","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Friday night at the roller rink, couples skate",2,"I held hands with Tammy Pruitt at the couples skate",1,"And?",2,"And she dropped me on the second lap, I've still got the scar",3,"Tammy Pruitt dropped half this county"}},
{"fw_ld6_shelter_civ_1_0102","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Kmart on a Saturday, the blue light flashing and my mom's elbow in everybody's ribs",2,"We got every pair of school shoes there",1,"I'd stand in that shoe aisle for an hour right now"}},
{"fw_ld6_shelter_civ_1_0103","shelter",3,"reg=civilian,family,worker,rescue",{1,"The ice cream truck, remember the music?",2,"The slow warped music",1,"If I heard that right now I'd run toward it",3,"You'd run toward anything with a freezer"}},
{"fw_ld6_shelter_civ_1_0104","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Five a.m., Papaw yelling about the cows",2,"Which cows?",1,"All of them, any of them, he didn't discriminate",2,"I miss being yelled at about cows"}},
{"fw_ld6_shelter_civ_1_0105","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Rectangle pizza on Fridays at school",2,"With the corn",1,"The corn was a different day",3,"The corn was always a different day"}},
{"fw_ld6_shelter_civ_1_0106","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I wore a baby blue tux to prom",2,"No",1,"Ruffled shirt, yeah, there's a picture somewhere",2,"I hope it burned",1,"It's at my mother's house, so it did not burn"}},
{"fw_ld6_shelter_civ_1_0107","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Wedding was in a church with a leaky roof, it rained on the cake",2,"Bad luck?",1,"Eleven years, no complaints about the cake",3,"Free shower, that's good luck"}},
{"fw_ld6_shelter_civ_1_0108","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Do you remember Chicken Man at the Sunday buffet",2,"Who",1,"The guy who stood by the fried chicken and watched you take a piece, like you owed him money",2,"...oh, God, yeah, he WATCHED you!"}},
{"fw_ld6_shelter_civ_1_0109","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"You know what I'd do if I could go back to any one day",2,"What",1,"The Sunday before, we had a cookout, nothing special, it was just a Sunday",2,"Nothing special's all I want",3,"Yeah..."}},
{"fw_ld6_shelter_civ_1_0110","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Remember phone calls with the cord stretched all the way into the closet",2,"Privacy",1,"My mother stood outside the closet door breathing",2,"Mine too, I could hear her"}},
{"fw_ld6_shelter_civ_1_0111","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Every year at Christmas my uncle would fall asleep in the recliner with a plate on his chest",2,"And?",1,"And one year the dog ate everything and he woke up with just a fork",2,"Did he say anything?",1,"He said thank you, to the dog",3,"Smart dog, he knew where the food was"}},
{"fw_ld6_shelter_civ_1_0112","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Friday night football, the band, popcorn, all of it",2,"The cheerleaders, the concession stand",1,"I'd give anything for a bad hot dog and a loud crowd",2,"A crowd's the last thing I want, I'd take the hot dog"}},
{"fw_ld6_shelter_civ_1_0113","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"My mamaw sang while she cooked, the same song every time",2,"Which one?",1,"I don't even know, I can only hum it",2,"Hum it",1,"Mm-mm-mmm... that's all I got",3,"That's more than I got of my mamaw"}},
{"fw_ld6_shelter_civ_1_0114","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Waffle House at three in the morning after the late shift",2,"The waitress knew your order",1,"Knew it before I sat down",2,"That's a real friend"}},
{"fw_ld6_shelter_civ_1_0115","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I won a turkey at the Kroger raffle in '89",2,"A live one?",1,"A frozen one, and I had to carry it home on the bus",2,"A frozen turkey on a bus, that's a very specific memory",1,"It's my proudest day",3,"Frozen turkey on a bus, that's a country song"}},
{"fw_ld6_shelter_civ_1_0116","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Summer job at the pool, I got paid four dollars an hour to yell at kids",2,"You were good at it",1,"I was great at it, I miss it so much"}},
{"fw_ld6_shelter_civ_1_0117","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"Do you remember what it sounded like before?",2,"Before what",1,"This, the sound, the trucks on Dixie Highway at night",2,"Yeah, I could fall asleep to that",1,"I'd give a lot for a truck to go by",3,"A truck, a horn, anything with an engine"}},
{"fw_ld6_shelter_civ_1_0118","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"My boy's baseball card collection is in the attic",2,"Anything good?",1,"A Reds rookie card, he'd kill me if I lost it",2,"You didn't lose it, you left it",1,"It's the same thing when you're ten"}},
{"fw_ld6_shelter_civ_1_0119","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Church picnic, the three-legged race, I fell on Pastor",2,"You did not",1,"Flat on top of him, I heard his glasses crunch",2,"Did he forgive you?",1,"He said he'd been wanting new glasses",3,"Pastor was a saint, he took that and a sermon in the same day"}},
{"fw_ld6_shelter_civ_1_0120","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Me and my brother once drove to Nashville on a dare",2,"And?",1,"And it was a Tuesday, nothing was open, we ate gas station chicken and drove home",2,"That's a good trip"}},
{"fw_ld6_shelter_civ_1_0121","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I'd give a month's pay for one more night shift at the plant, with the break room and the bad coffee",2,"You hated that plant",1,"I hated every minute of it, and I'd be there right now",3,"We all would, don't lie..."}},
{"fw_ld6_shelter_civ_1_0122","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Remember when the whole street came out for the Fourth, every house had a flag and somebody's uncle had a cannon",2,"It was a lawn mower with a pipe",1,"It was a very loud lawn mower with a pipe"}},
{"fw_ld6_shelter_civ_1_0123","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I could drive to my sister's with my eyes closed, you take the left at the Shell, the road goes by the old cemetery",2,"And then",1,"And then it's a hill, a long one, and her house is on the left, with the green shutters",3,"You're telling it like you're already there"}},
{"fw_ld6_shelter_civ_1_0124","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"Tried Mama's number before the line died",2,"Anybody pick up?",1,"It rang, just rang, like normal, like she was out back hanging wash",2,"That's something",1,"Is it?"}},
{"fw_ld6_shelter_civ_1_0125","shelter",4,"reg=civilian,family,worker,rescue|mood=fear",{1,"My brother's at Fort Knox, they'd have called, right?",2,"Called how",1,"I-- I don't know, somebody, a letter, anything",2,"There's no mail",1,"I KNOW there's no mail!",3,"Somebody'll come through, a runner, somebody"}},
{"fw_ld6_shelter_civ_1_0126","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"Last I knew, my girl was at her dad's in Lexington",2,"That's what, a hundred miles?",1,"About a hundred and ten from the old house. Feels longer when I can't call",2,"Does she know where we are",1,"She knew where I'd try to go. That's the best I can say"}},
{"fw_ld6_shelter_civ_1_0127","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"My sister's due in September",2,"Where's she at?",1,"Louisville, apartment, third floor, no elevator",2,"She sounds tough",1,"You don't know her",2,"No, I'm trying to help",3,"It helps, don't stop"}},
{"fw_ld6_shelter_civ_1_0128","shelter",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Dad's got three oxygen tanks and one of them was half empty",2,"How long does that-",1,"Don't do the math, I did the math"}},
{"fw_ld6_shelter_civ_1_0129","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I filled the dog's bowl all the way before we left",2,"He's a smart dog",1,"He's a stupid dog, he ate a sock last week",2,"Then he'll eat the bowl and be fine",3,"He'll find the neighbors' trash..."}},
{"fw_ld6_shelter_civ_1_0130","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I didn't even say goodbye, I yelled see you at supper and went to work",2,"Everybody did that",1,"I know, but it's all I think about"}},
}
